contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function driving the test
    function run(uint putLock, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // ensure this test contract has funds to send
        require(address(this).balance >= amount);

        // observe holder before state via public getter Acc(address)
        (uint beforeUnlock, uint beforeAccBal) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint beforeCbal = address(c).balance;

        // Attempt Put with value `amount`. Capture whether it reverted.
        bool reverted;
        c.Put{value: amount}(putLock); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after state
        (uint afterUnlock, uint afterAccBal) = c.Acc(address(this)); if (__ESBMC_reverted()) return;
        uint afterCbal = address(c).balance;

        // General invariant: if Put succeeded, the recorded holder balance must not have decreased.
        // (It may increase by at most amount, but we only require non-decrease here.)
        assert(reverted || afterAccBal >= beforeAccBal);
    }

    receive() external payable {}
}

